import pandas as pd
import numpy as np

# Load the dataset
df = pd.read_csv('chunks_csv/moran_local_2022_waste.csv')

# Load the adjacency list
adjacency = pd.read_csv(ADJACENCY_PATH)

# Define a function to calculate Moran's I
def moran_i(data, weights):
    n = len(data)
    x = data.values
    w = weights.values
    sum_w = np.sum(w)
    sum_x = np.sum(x * w)
    sum_x2 = np.sum(x**2 * w)
    sum_xw = np.sum(x * w**2)
    I = (n * sum_xw - sum_w**2) / (n - 1) / (sum_w**2 - n * sum_w * sum_w)
    return I

# Define a function to calculate the neighbors of a borough
def get_neighbors(borough):
    neighbors = []
    for i, row in adjacency.iterrows():
        if row['borough'] == borough:
            neighbors.append(row['neighbor'])
    return neighbors

# Define a function to calculate the average waste generation of a borough and its neighbors
def get_average_waste(borough):
    neighbors = get_neighbors(borough)
    data = df[df['borough'].isin(neighbors)]
    return np.mean(data['waste_generation'])

# Define a function to check if a borough is a hot spot or a cold spot
def is_hot_cold_spot(borough):
    avg_waste = get_average_waste(borough)
    if borough in df['borough'].unique() and avg_waste > np.mean(df['waste_generation']):
        return 'HOT SPOT'
    elif borough in df['borough'].unique() and avg_waste < np.mean(df['waste_generation']):
        return 'COLD SPOT'
    else:
        return None

# Calculate Moran's I for each borough
I_values = {}
for index, row in df.iterrows():
    I = moran_i(row['waste_generation'], row['weights'])
    I_values[row['borough']] = I

# Print the I values
for borough, I in I_values.items():
    print(f'{borough}: I = {I}')

# Check if a borough is a hot spot or a cold spot
hot_cold_spots = {}
for index, row in df.iterrows():
    if is_hot_cold_spot(row['borough']) is not None:
        hot_cold_spots[row['borough']] = is_hot_cold_spot(row['borough'])

# Print the hot and cold spots
for borough, spot in hot_cold_spots.items():
    print(f'{borough} ({spot})')

# Print the final answer
hot_cold_spots_list = []
for borough, spot in hot_cold_spots.items():
    if spot == 'HOT SPOT':
        hot_cold_spots_list.append(f'{borough} (HH, I={I_values[borough]})')
    elif spot == 'COLD SPOT':
        hot_cold_spots_list.append(f'{borough} (LL, I={I_values[borough]})')
print('FINAL ANSWER:', ', '.join(hot_cold_spots_list))
